def calculate_max_utilization(task_set):
    U_M = 0.0
    for task_i in task_set:
        U_M_i = task_i.C / task_i.T
        U_M += U_M_i
    return U_M

def calculate_min_utilization(task_set):
    U_m = 0.0
    for task_i in task_set:
        U_m_i = (task_i.C / task_i.T) * ((task_i.K - task_i.m) / task_i.K)
        U_m += U_m_i
    return U_m

class JobClass:
    def __init__(self, task_id, q_index):
        self.task_id = task_id
        self.q_index = q_index
        self.priority = None # Assigned later

def determine_job_class(task_i, consecutive_meets_count):
    q = min(consecutive_meets_count, task_i.K - task_i.m)
    return JobClass(task_i.id, q)

def record_mu_pattern(job_results):
    mu_pattern_str = ""
    for result in job_results:
        if result == 'MET':
            mu_pattern_str += 'M'
        else:
            mu_pattern_str += 'm'
    return mu_pattern_str

def record_C_pattern(job_class_indices):
    C_pattern_str = "".join(str(q) for q in job_class_indices)
    return C_pattern_str

def calculate_miss_threshold(task_i):
    if task_i.K - task_i.m == 0: # Avoid division by zero for hard real-time
        return 1 # Or handle as error/special case
    return max(floor(task_i.K / (task_i.K - task_i.m)) - 1, 1)

def assign_job_class_with_threshold(task_i, current_consecutive_meets, consecutive_misses_count):
    w_i = calculate_miss_threshold(task_i)
    if consecutive_misses_count >= w_i:
        return 0 # Force to J_0_i
    else:
        return min(current_consecutive_meets, task_i.K - task_i.m)

def simulate_task_level_scheduling(task_i, task_priority):
    # In job-class-level scheduler, set all job-class priorities to task_priority
    for q in range(0, task_i.K - task_i.m + 1):
        task_i.job_classes[q].priority = task_priority
    # Now, the job-class-level scheduler will behave like a task-level one for task_i

