def check_prerequisite_schedulability(task_i, WCRT_J_0_i):
    if WCRT_J_0_i > task_i.D:
        return False # Task is unschedulable
    return True # Prerequisite met

def calculate_interference(t, task_i, q_index, task_k, job_classes_k_etas):
    priority_J_q_i = task_i.job_classes[q_index].priority

    interference_sum_eta = 0
    has_higher_priority_job_class = False
    for p_index, J_p_k_data in enumerate(task_k.job_classes):
        if J_p_k_data.priority > priority_J_q_i:
            has_higher_priority_job_class = True
            # eta_J_p_k would be pre-calculated and stored in J_p_k_data
            eta_J_p_k = job_classes_k_etas[p_index]
            interference_sum_eta += floor((t + task_k.J) / eta_J_p_k) * task_k.C

    if not has_higher_priority_job_class:
        return 0

    interference_task_level = floor((t + task_k.J) / task_k.T) * task_k.C

    return min(interference_sum_eta, interference_task_level)

def calculate_wcrt_job_class(task_i, q_index, task_set, precomputed_etas):
    R_q_n_i = task_i.C
    while True:
        R_q_n_plus_1_i = task_i.C
        total_interference = 0
        for task_k in task_set:
            if task_k.id != task_i.id:
                total_interference += calculate_interference(R_q_n_i, task_i, q_index, task_k, precomputed_etas[task_k.id])

        R_q_n_plus_1_i += total_interference

        if R_q_n_plus_1_i == R_q_n_i:
            return R_q_n_plus_1_i + task_i.J # Converged, add jitter for final WCRT

        if R_q_n_plus_1_i + task_i.J > task_i.D:
            return float('inf') # Deadline miss

        R_q_n_i = R_q_n_plus_1_i

def is_schedulable_by_ratio(task_i, WCRT_J_0_i):
    if task_i.m / task_i.K >= 0.5:
        if WCRT_J_0_i <= task_i.D:
            return True
    return False

