def check_task_schedulability_via_trees(task_i, all_reachability_trees):
    for tree in all_reachability_trees:
        for leaf_node in tree.leaf_nodes:
            mu_pattern = leaf_node['mu_pattern']
            misses_count = mu_pattern.count('m')
            if misses_count > task_i.m:
                return False # Found a pattern that violates constraint
    return True # All patterns satisfy constraint

def calculate_fibonacci_nodes(depth):
    if depth == 0: return 1 # Root node
    if depth == 1: return 2 # Max 2 children from root (J0_i meets, J0_i misses)

    f_prev2 = 1 # N_nodes_depth_0
    f_prev1 = 2 # N_nodes_depth_1
    for i in range(2, depth + 1):
        f_current = f_prev1 + f_prev2
        f_prev2 = f_prev1
        f_prev1 = f_current
    return f_current
